PRACTICE = [
  { id: 'pr-1', spread: 'tarot-1', free: true, course: 'tarot',
    cards: ['major-0'], rev: [0], frames: ['state'], traps: [],
    who: { vi: 'Một bạn nữ 24 tuổi vừa được mời sang một thành phố khác làm việc. Bạn ấy chưa trả lời.',
           en: 'A woman of 24 has been offered a job in another city. She has not answered yet.',
           de: 'Einer 24-Jährigen wurde eine Stelle in einer anderen Stadt angeboten. Sie hat noch nicht geantwortet.' },
    q: { vi: 'Điều gì tôi cần biết nhất về lời mời này, ngay lúc này?',
         en: 'What do I most need to know about this offer right now?',
         de: 'Was muss ich über dieses Angebot gerade jetzt vor allem wissen?' },
    model: { vi: 'Lá này nói về một cánh cửa vừa mở và một bước chân chưa đặt xuống. Nó không nói lời mời tốt hay xấu — nó nói rằng thứ đang giữ bạn ấy lại là chưa quen, chứ không phải là nguy hiểm. Đọc một lá thì đừng rút thêm lá thứ hai để làm dịu lá thứ nhất.',
             en: 'This card is about a door that has opened and a step not yet taken. It does not say the offer is good or bad; it says what is holding her back is unfamiliarity, not danger. With one card, do not reach for a second to soften the first.',
             de: 'Diese Karte handelt von einer offenen Tür und einem Schritt, der noch nicht getan ist. Sie sagt nicht, ob das Angebot gut oder schlecht ist, sondern dass sie das Ungewohnte zurückhält, nicht die Gefahr. Bei einer Karte nicht nach einer zweiten greifen, um die erste abzumildern.' } },

  { id: 'pr-2', spread: 'tarot-3', free: true, course: 'tarot',
    cards: ['cups-3', 'swords-5', 'major-6'], rev: [0, 1, 0], frames: ['state', 'advice', 'outcome'], traps: ['reversal'],
    who: { vi: 'Hai người bạn thân vừa giận nhau sau một buổi tụ tập đông người. Một trong hai người đến hỏi bài.',
           en: 'Two close friends fell out after a crowded get-together. One of them comes for a reading.',
           de: 'Zwei enge Freundinnen haben sich nach einem vollen Treffen zerstritten. Eine von beiden kommt zur Legung.' },
    q: { vi: 'Chuyện giữa chúng tôi đang ở đâu, tôi nên làm gì, và nó sẽ dẫn tới đâu?',
         en: 'Where does this stand between us, what should I do, and where does it lead?',
         de: 'Wo stehen wir, was soll ich tun, und wohin führt das?' },
    model: { vi: 'Lá giữa nằm ngược, nên đừng đọc nó như một cuộc thắng thua nữa — nó nói chuyện thắng thua đang được buông xuống. Vị trí hai là lời khuyên, nên câu của bạn ở đó phải là một việc để làm, không phải một dự đoán. Lá ba là nơi hai bên gặp lại nhau nếu lời khuyên kia được nghe.',
             en: 'The middle card is reversed, so stop reading it as winning and losing; it says the scorekeeping is being put down. Position two is advice, so your sentence there must be something to do, not something foretold. Card three is where the two meet again if that advice is taken.',
             de: 'Die mittlere Karte liegt umgekehrt, also nicht mehr als Sieg und Niederlage lesen: Sie sagt, dass das Aufrechnen abgelegt wird. Position zwei ist ein Rat, also muss dein Satz dort etwas zu Tuendes sein, keine Vorhersage. Karte drei ist der Ort, an dem beide sich wiederfinden, wenn dieser Rat befolgt wird.' } },

  { id: 'pr-3', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['pentacles-8', 'wands-7', 'pentacles-10'], rev: [0, 0, 0], frames: ['state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một người đàn ông 31 tuổi đã làm cùng một nghề sáu năm và đang bị rủ sang một chỗ mới.',
           en: 'A man of 31 has done the same work for six years and is being courted by somewhere new.',
           de: 'Ein 31-Jähriger macht seit sechs Jahren dieselbe Arbeit und wird von einer neuen Stelle umworben.' },
    q: { vi: 'Công việc của tôi đang ở đâu, tôi nên làm gì, và con đường này dẫn tới đâu?',
         en: 'Where does my work stand, what should I do, and where does this path lead?',
         de: 'Wo steht meine Arbeit, was soll ich tun, und wohin führt dieser Weg?' },
    model: { vi: 'Ba lá đều là chuyện làm lụng, không có lá Ẩn Chính nào, nên chuyện này nằm trong tay anh ấy chứ không phải trong tay số phận. Vị trí hai không bảo anh ấy đi hay ở — nó bảo anh ấy giữ chỗ đứng của mình. Lá ba là thứ tích lại được nếu anh ấy không bỏ dở giữa chừng.',
             en: 'All three are working cards and not one Major, so this is in his hands rather than in fate’s. Position two does not tell him to go or stay; it tells him to hold his ground. Card three is what accumulates if he does not walk away halfway.',
             de: 'Alle drei sind Arbeitskarten und keine einzige Große Arkana, also liegt das in seiner Hand und nicht im Schicksal. Position zwei sagt ihm nicht, ob er gehen oder bleiben soll, sondern dass er seinen Stand halten soll. Karte drei ist das, was sich ansammelt, wenn er nicht auf halbem Weg aufgibt.' } },

  { id: 'pr-4', spread: 'tarot-yesno', free: false, course: 'tarot',
    cards: ['cups-5', 'wands-3', 'major-10', 'swords-2', 'pentacles-4'], rev: [1, 0, 0, 1, 0],
    frames: ['state', 'state', 'state', 'state', 'state'], traps: ['bare'],
    who: { vi: 'Một người hỏi một câu đóng, chỉ có hai khả năng trả lời.',
           en: 'Someone asks a closed question with only two possible answers.',
           de: 'Jemand stellt eine geschlossene Frage mit nur zwei möglichen Antworten.' },
    q: { vi: 'Tôi có nên nhận lời đi dự buổi gặp mặt đó không?',
         en: 'Should I say yes to that meeting?',
         de: 'Soll ich dieser Verabredung zusagen?' },
    model: { vi: 'Đếm trước: ba lá xuôi, hai lá ngược, nên câu trả lời là có — nhưng một chữ “có” trơ trọi thì không phải một bài đọc, nó là tung đồng xu có hình. Lá giữa mới nói đó là cái “có” kiểu gì, và lá Ẩn Chính trong hàng nói chuyện này không hoàn toàn do người hỏi định đoạt.',
             en: 'Count first: three upright against two reversed, so the answer is yes — but a bare "yes" is not a reading, it is a coin toss with pictures. The middle card is what says which kind of yes it is, and the Major in the row says this is not entirely the asker’s to decide.',
             de: 'Erst zählen: drei aufrecht gegen zwei umgekehrt, also lautet die Antwort ja — aber ein nacktes „Ja“ ist keine Legung, sondern ein Münzwurf mit Bildern. Die mittlere Karte sagt, welche Art von Ja es ist, und die Große Arkana in der Reihe sagt, dass dies nicht allein der Fragenden überlassen ist.' } },

  { id: 'pr-5', spread: 'tarot-time', free: false, course: 'tarot',
    cards: ['swords-4', 'wands-8', 'cups-9', 'major-21'], rev: [0, 0, 0, 0],
    frames: ['state', 'state', 'state', 'state'], traps: ['date'],
    who: { vi: 'Người hỏi đã chốt đơn vị thời gian trước khi xào bài: bốn tháng.',
           en: 'The asker fixed the unit before shuffling: four months.',
           de: 'Die Fragende hat die Einheit vor dem Mischen festgelegt: vier Monate.' },
    q: { vi: 'Bao giờ chuyện tôi đang chờ mới chuyển?',
         en: 'When will the thing I am waiting for move?',
         de: 'Wann bewegt sich das, worauf ich warte?' },
    model: { vi: 'Tháng đầu là nằm yên, tháng hai mới là lúc mọi thứ chạy, và tháng ba là chỗ nhận được. Tarot mô tả trình tự chứ không gọi ra ngày; ai viết “khoảng ngày 20 tháng sau” là đang bịa thêm một thứ mà bốn lá này không nói.',
             en: 'The first stretch is stillness, the second is when things actually move, and the third is where it arrives. Tarot describes sequence and does not name dates; anyone writing "around the 20th of next month" is adding something these four cards did not say.',
             de: 'Der erste Abschnitt ist Stillstand, im zweiten kommt wirklich Bewegung, und im dritten kommt es an. Tarot beschreibt Abfolge und nennt keine Daten; wer „etwa am 20. nächsten Monats“ schreibt, erfindet etwas, das diese vier Karten nicht gesagt haben.' } },

  { id: 'pr-6', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['major-19', 'pentacles-5', 'cups-4'], rev: [1, 0, 1], frames: ['state', 'advice', 'outcome'], traps: ['reversal'],
    who: { vi: 'Một người vừa qua một giai đoạn dài mệt mỏi và đang hỏi về sức khoẻ tinh thần của mình.',
           en: 'Someone has come through a long tiring stretch and asks about their own state of mind.',
           de: 'Jemand hat eine lange anstrengende Zeit hinter sich und fragt nach dem eigenen Gemütszustand.' },
    q: { vi: 'Tôi đang ở đâu, tôi nên làm gì, và nếu cứ thế này thì sẽ ra sao?',
         en: 'Where am I, what should I do, and what happens if this goes on?',
         de: 'Wo stehe ich, was soll ich tun, und was passiert, wenn das so weitergeht?' },
    model: { vi: 'Hai trong ba lá nằm ngược, nên bài này kiểm tra đúng một chuyện: bạn có đọc mặt trái hay vẫn đọc mặt phải rồi thêm chữ “không” vào. Lá đầu ngược không phải là hết nắng, nó là nắng bị che. Lá cuối ngược là chỗ mở ra, không phải chỗ đóng lại.',
             en: 'Two of the three are reversed, so this exercise tests exactly one thing: whether you read the shadow, or read the upright and put "not" in front of it. The first reversed is not the sun gone, it is the sun covered. The last reversed is where something opens, not where it closes.',
             de: 'Zwei der drei liegen umgekehrt, also prüft diese Übung genau eines: ob du die Schattenseite liest oder die aufrechte Bedeutung nimmst und ein „nicht“ davorsetzt. Die erste Umgekehrte ist nicht die verschwundene Sonne, sondern die verdeckte. Die letzte Umgekehrte ist, wo sich etwas öffnet, nicht wo es sich schließt.' } }
,

  { id: 'pr-7', spread: 'tarot-1', free: false, course: 'tarot',
    cards: ['swords-c2'], rev: [0], frames: ['state'], traps: [],
    who: { vi: 'Một bạn nữ 27 tuổi thấy người yêu hay úp điện thoại xuống và đổi giọng mỗi khi nhắc tới một đồng nghiệp. Bạn ấy không biết mình đang tinh ý hay đang tự doạ mình.',
           en: 'A woman of 27 notices her partner turning his phone face down and changing his tone whenever one colleague comes up. She cannot tell whether she is noticing something or frightening herself.',
           de: 'Eine 27-Jährige bemerkt, dass ihr Partner sein Handy umdreht und den Ton wechselt, sobald eine bestimmte Kollegin erwähnt wird. Sie weiß nicht, ob sie etwas sieht oder sich selbst Ängste macht.' },
    q: { vi: 'Thứ tôi đang cảm thấy là linh cảm hay là nỗi lo của riêng tôi?',
         en: 'Is what I am feeling my intuition, or my own fear?',
         de: 'Ist das, was ich spüre, meine Intuition oder meine eigene Angst?' },
    model: { vi: 'Lá này là cái nhìn sắc, nhìn xuyên qua lời nói — nó nói bạn ấy đang thấy thật chứ không tưởng tượng. Nhưng một lá trả lời cho câu “chuyện gì”, không trả lời cho câu “ai đúng ai sai”. Đừng biến một lá bài thành lời buộc tội một người không có mặt ở đây.',
             en: 'This card is clear sight, the kind that hears past the words — it says she is noticing something real rather than inventing it. But one card answers a what, not a who is guilty. Do not turn a single card into an accusation of someone who is not in the room.',
             de: 'Diese Karte ist der klare Blick, der hinter die Worte hört — sie sagt, dass die Fragende etwas Echtes wahrnimmt und es sich nicht ausdenkt. Aber eine Karte beantwortet ein Was, kein Wer ist schuld. Mach aus einer einzelnen Karte keine Anklage gegen jemanden, der nicht dabei ist.' } },

  { id: 'pr-8', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['major-9', 'pentacles-3', 'major-17'], rev: [0, 0, 0], frames: ['state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một người vừa qua sinh nhật 30. Bạn bè cùng lớp đã có nhà, có con, còn mình thì chưa đâu vào đâu.',
           en: 'Someone has just turned 30. Their classmates have homes and children; they feel nothing of theirs has settled.',
           de: 'Jemand ist gerade 30 geworden. Die früheren Mitschüler haben Häuser und Kinder; bei ihm selbst hat sich nichts gesetzt.' },
    q: { vi: 'Tôi đang ở đâu, tôi nên làm gì, và nếu cứ thế này thì sẽ ra sao?',
         en: 'Where am I, what should I do, and what happens if this goes on?',
         de: 'Wo stehe ich, was soll ich tun, und was passiert, wenn das so weitergeht?' },
    model: { vi: 'Hai trong ba lá là ᡈn Chính, nên chuyện này lớn hơn câu hỏi vừa đặt ra: đây không phải chuyện chậm tiến độ, đây là chuyện đo mình bằng thước của người khác. Lá đầu là đi chậm có chủ đích, không phải tụt lại. Vị trí hai là lời khuyên, nên câu của bạn ở đó phải là một việc làm được trong tuần này.',
             en: 'Two of the three are Majors, so this is larger than the question asked: it is not about being behind schedule, it is about measuring a life with somebody else’s ruler. The first card is walking slowly on purpose, not falling behind. Position two is advice, so your sentence there has to be something doable this week.',
             de: 'Zwei der drei sind Große Arkana, also ist das größer als die gestellte Frage: Es geht nicht um Verzögerung, sondern darum, das eigene Leben mit fremdem Maß zu messen. Die erste Karte geht absichtlich langsam, sie fällt nicht zurück. Position zwei ist ein Rat, dein Satz dort muss also diese Woche machbar sein.' } },

  { id: 'pr-9', spread: 'tarot-choice', free: false, course: 'tarot',
    cards: ['major-2', 'cups-8', 'pentacles-4', 'wands-8', 'cups-10'], rev: [0, 0, 0, 0, 0],
    frames: ['state', 'state', 'outcome', 'state', 'outcome'], traps: [],
    who: { vi: 'Một cặp vợ chồng phân vân giữa bán căn nhà cũ để đổi chỗ, hay giữ lại và sửa.',
           en: 'A couple cannot decide between selling the old house and moving, or keeping it and renovating.',
           de: 'Ein Paar kann sich nicht entscheiden: das alte Haus verkaufen und umziehen, oder es behalten und renovieren.' },
    q: { vi: 'Hai con đường này khác nhau thế nào, và mỗi con dẫn chúng tôi tới đâu?',
         en: 'How do these two roads differ, and where does each of them take us?',
         de: 'Wie unterscheiden sich diese beiden Wege, und wohin führt uns jeder davon?' },
    model: { vi: 'Trải bài này không chọn hộ ai cả — nó mô tả hai con đường để người hỏi tự chọn. Đừng đọc năm lá thành năm câu rời: đọc lá một là chỗ hai người đang đứng, rồi đặt hai nhánh cạnh nhau mà so. Một nhánh là rời đi để giữ lấy thứ gì đó, nhánh kia là ở lại và giữ chặt.',
             en: 'This spread chooses for nobody — it lays out two roads so the asker can choose. Do not read five cards as five separate sentences: read card one as where the two of them stand, then set the branches side by side and compare. One branch is leaving in order to keep something; the other is staying and holding on.',
             de: 'Diese Legung entscheidet für niemanden — sie zeigt zwei Wege, damit die Fragenden selbst wählen. Lies fünf Karten nicht als fünf einzelne Sätze: Karte eins ist, wo die beiden stehen; dann stell die Zweige nebeneinander und vergleiche. Ein Zweig geht fort, um etwas zu bewahren; der andere bleibt und hält fest.' } },

  { id: 'pr-10', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['pentacles-7', 'swords-8', 'pentacles-6'], rev: [0, 1, 0], frames: ['state', 'advice', 'outcome'], traps: ['reversal'],
    who: { vi: 'Một người 34 tuổi đang trả nợ thẻ tín dụng. Tháng nào cũng trả được khoản tối thiểu, nhưng số nợ không bao giờ vơi.',
           en: 'Someone of 34 is paying down a credit card. The minimum goes out every month and the balance never falls.',
           de: 'Eine 34-Jährige zahlt eine Kreditkarte ab. Jeden Monat geht die Mindestrate raus, und der Saldo sinkt nie.' },
    q: { vi: 'Tiền bạc của tôi đang ở đâu, tôi nên làm gì, và nó sẽ dẫn tới đâu?',
         en: 'Where do my finances stand, what should I do, and where does that lead?',
         de: 'Wo stehen meine Finanzen, was soll ich tun, und wohin führt das?' },
    model: { vi: 'Lá giữa nằm ngược, nên đừng đọc nó như một người bị trói nữa — nó nói dây đang được cởi, rằng người này bắt đầu nhìn ra mình không kẹt như mình tưởng. Lá đầu là đứng nhìn thứ mình đã trồng mà chưa thấy quả: đúng là cảm giác trả mãi không vơi.',
             en: 'The middle card is reversed, so stop reading it as someone tied up — it says the rope is coming loose, that they are starting to see they are less stuck than they believed. The first card is standing over something planted that has not fruited yet: exactly the feeling of paying and paying with nothing to show.',
             de: 'Die mittlere Karte liegt umgekehrt, also lies sie nicht mehr als jemanden, der gefesselt ist — sie sagt, dass sich der Strick löst und die Fragende zu sehen beginnt, dass sie weniger feststeckt als gedacht. Die erste Karte steht vor etwas Gepflanztem, das noch keine Frucht trägt: genau das Gefühl, immer zu zahlen ohne Ergebnis.' } },

  { id: 'pr-11', spread: 'tarot-rel7', free: false, course: 'tarot',
    cards: ['cups-2', 'swords-3', 'wands-c1', 'cups-9', 'swords-6', 'pentacles-9', 'major-14'], rev: [0, 0, 0, 0, 0, 0, 0],
    frames: ['state', 'state', 'state', 'state', 'state', 'state', 'outcome'], traps: [],
    who: { vi: 'Hai người yêu nhau hai năm, một năm nay ở hai nước. Cả hai đều nói mình ổn, nhưng cuộc gọi ngày một ngắn.',
           en: 'Two people together for two years, the last one in different countries. Both say they are fine, and the calls get shorter.',
           de: 'Zwei Menschen, zwei Jahre zusammen, das letzte davon in verschiedenen Ländern. Beide sagen, es gehe ihnen gut, und die Anrufe werden kürzer.' },
    q: { vi: 'Mỗi người đang ở đâu trong chuyện này, và giữa chúng tôi còn lại gì?',
         en: 'Where is each of us in this, and what is still between us?',
         de: 'Wo steht jeder von uns darin, und was ist noch zwischen uns?' },
    model: { vi: 'Bảy lá thì đừng đọc bảy lần. Đọc theo ba cột: phía bạn, phía người kia, và lá ở giữa. Hai cột này không đối xứng nhau — một bên đang giữ, một bên đang đi, và đó mới là câu trả lời. Lá cuối là thứ phải pha trộn chậm rãi mới thành, không phải thứ quyết trong một cuộc gọi.',
             en: 'Seven cards is not seven readings. Read it as three columns: your side, their side, and the card between. The two columns are not symmetrical — one is holding, one is moving, and that asymmetry is the answer. The last card is something blended slowly, not something settled in one phone call.',
             de: 'Sieben Karten sind nicht sieben Deutungen. Lies sie als drei Spalten: deine Seite, seine Seite und die Karte dazwischen. Die beiden Spalten sind nicht symmetrisch — eine hält, eine geht, und genau diese Schieflage ist die Antwort. Die letzte Karte wird langsam gemischt, nicht in einem Telefonat entschieden.' } },

  { id: 'pr-12', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['swords-c3', 'wands-5', 'swords-6'], rev: [0, 0, 0], frames: ['state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một người vào công ty được sáu tháng, gặp một quản lý hay nói gắt trước mặt cả phòng.',
           en: 'Someone six months into a job has a manager who speaks sharply in front of the whole room.',
           de: 'Jemand ist seit sechs Monaten in einer Firma und hat einen Vorgesetzten, der vor allen scharf wird.' },
    q: { vi: 'Chuyện với sếp tôi đang ở đâu, tôi nên làm gì, và nó dẫn tới đâu?',
         en: 'Where does this stand with my manager, what should I do, and where does it lead?',
         de: 'Wo stehe ich mit meinem Vorgesetzten, was soll ich tun, und wohin führt das?' },
    model: { vi: 'Lá đầu là một lá hoàng gia, và lá hoàng gia thường là một người thật. Đọc nó như tính cách của người đó — sắc, thẳng, không đệm — chứ đừng đọc thành một thứ năng lượng chung chung. Lá giữa không bảo người hỏi nhẫn nhịn cũng không bảo đối đầu: nó nói chuyện đang ồn ào hơn là nguy hiểm.',
             en: 'The first card is a court card, and a court card is usually a real person. Read it as that person’s character — sharp, direct, unpadded — not as some general energy. The middle card neither tells them to endure it nor to fight: it says the situation is noisier than it is dangerous.',
             de: 'Die erste Karte ist eine Hofkarte, und eine Hofkarte ist meist ein realer Mensch. Lies sie als den Charakter dieser Person — scharf, direkt, ungepolstert — nicht als allgemeine Energie. Die mittlere Karte rät weder zum Ertragen noch zum Kampf: Sie sagt, die Lage ist lauter als gefährlich.' } },

  { id: 'pr-13', spread: 'tarot-1', free: false, course: 'tarot',
    cards: ['cups-5'], rev: [1], frames: ['state'], traps: ['reversal'],
    who: { vi: 'Một người mất mẹ tám tháng trước. Gần đây đã cười được, rồi lại thấy có lỗi vì mình cười.',
           en: 'Someone lost their mother eight months ago. Lately they have laughed again, and then felt guilty for laughing.',
           de: 'Jemand hat vor acht Monaten die Mutter verloren. In letzter Zeit hat er wieder gelacht — und sich dafür schuldig gefühlt.' },
    q: { vi: 'Tôi đang ở đâu trong nỗi mất mát này?',
         en: 'Where am I in this loss?',
         de: 'Wo stehe ich in diesem Verlust?' },
    model: { vi: 'Lá này xuôi là quay lưng về phía những cái cốc đã đổ. Nằm ngược thì là quay lại, nhìn thấy hai cái cốc còn đứng — không phải hết buồn, mà là bắt đầu thấy cả những thứ chưa mất. Bài đọc về mất mát thì không dự đoán, không hứa hẹn, cũng không giục ai nguôi đi — nó chỉ gọi tên chỗ người ta đang đứng.',
             en: 'Upright this card has its back to the spilled cups. Reversed, it is the turn of the head — seeing the two still standing. That is not grief ending; it is beginning to see what was not lost. A reading about loss does not predict, does not promise, and never hurries anyone: it names where they are standing.',
             de: 'Aufrecht kehrt diese Karte den umgestoßenen Bechern den Rücken zu. Umgekehrt ist sie die Drehung des Kopfes — das Sehen der beiden, die noch stehen. Das ist kein Ende der Trauer, sondern der Anfang davon, auch das Unverlorene zu sehen. Eine Legung über Verlust sagt nichts voraus, verspricht nichts und drängt niemanden: Sie benennt, wo jemand steht.' } },

  { id: 'pr-14', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['major-6', 'swords-2', 'cups-6'], rev: [0, 0, 1], frames: ['state', 'advice', 'outcome'], traps: ['reversal'],
    who: { vi: 'Một người 29 tuổi nhận tin nhắn của bố sau mười hai năm không liên lạc. Bố muốn gặp.',
           en: 'A 29-year-old gets a message from their father after twelve years of silence. He wants to meet.',
           de: 'Eine 29-Jährige bekommt nach zwölf Jahren Funkstille eine Nachricht von ihrem Vater. Er möchte sich treffen.' },
    q: { vi: 'Chuyện này đang ở đâu, tôi nên làm gì, và nếu tôi gặp thì sẽ ra sao?',
         en: 'Where does this stand, what should I do, and what happens if I go?',
         de: 'Wo steht das, was soll ich tun, und was passiert, wenn ich hingehe?' },
    model: { vi: 'Lá đầu không phải chuyện yêu đương — ở đây nó là một lựa chọn giữa hai con người mình có thể trở thành. Lá cuối nằm ngược: ký ức tuổi nhỏ lật ngược không còn là chỗ ấm áp để quay về, mà là thứ giữ người ta ở lại. Vị trí hai là lời khuyên, và lá đó không bảo gặp hay không gặp — nó bảo bỏ băng bịt mắt ra trước đã.',
             en: 'The first card is not romance here — it is a choice between two people you could become. The last is reversed: a childhood memory turned over is no longer a warm place to return to, it is the thing keeping you there. Position two is advice, and that card says neither go nor stay away — it says take the blindfold off first.',
             de: 'Die erste Karte ist hier keine Romanze — sie ist eine Wahl zwischen zwei Menschen, die man werden kann. Die letzte liegt umgekehrt: eine umgedrehte Kindheitserinnerung ist kein warmer Ort mehr, zu dem man zurückkehrt, sondern das, was einen dort festhält. Position zwei ist ein Rat, und diese Karte sagt weder hingehen noch fernbleiben — sie sagt: nimm zuerst die Augenbinde ab.' } },

  { id: 'pr-15', spread: 'tarot-clarify', free: false, course: 'tarot',
    cards: ['major-18', 'cups-7'], rev: [0, 0], frames: ['state', 'state'], traps: [],
    who: { vi: 'Một bài đọc vừa xong để lại nhiều thắc mắc hơn là làm rõ. Người hỏi rút thêm hai lá.',
           en: 'A reading has just left more confusion than it cleared. The asker draws two more cards.',
           de: 'Eine Legung hat mehr Verwirrung hinterlassen als geklärt. Die Fragende zieht zwei weitere Karten.' },
    q: { vi: 'Những lá tôi vừa rút thật ra đang nói gì?',
         en: 'What were the cards I just drew actually saying?',
         de: 'Was haben die Karten, die ich gerade gezogen habe, eigentlich gesagt?' },
    model: { vi: 'Lá làm rõ không thay lá cũ và cũng không hủy nó — nó nói lại lá cũ bằng một giọng khác. Nhưng cả hai lá ở đây đều là lá của sương mù và của những hình ảnh không có thật. Khi lá làm rõ cũng mờ nốt, thì chỗ mờ không nằm ở bộ bài — nó nằm ở câu hỏi. Việc cần làm là hỏi lại cho rõ, không phải rút thêm lá thứ ba.',
             en: 'A clarifier does not replace the first card or cancel it — it says the same card in another voice. But both cards here are cards of fog and of pictures that are not real. When the clarifier is hazy too, the haze is not in the deck — it is in the question. The move is to ask again more clearly, not to draw a third card.',
             de: 'Eine Klärungskarte ersetzt die erste nicht und hebt sie nicht auf — sie sagt dieselbe Karte mit anderer Stimme. Doch beide Karten hier sind Karten des Nebels und der Trugbilder. Wenn auch die Klärung trüb ist, liegt die Trübung nicht im Deck, sondern in der Frage. Jetzt fragt man klarer — man zieht keine dritte Karte.' } },

  { id: 'pr-16', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['pentacles-c0', 'swords-9', 'wands-6'], rev: [0, 0, 0], frames: ['state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một bạn vừa được nhận vào một khoá học khó, và lúc nào cũng thấy người ta nhận nhầm mình.',
           en: 'Someone has been accepted onto a hard course and keeps feeling they were let in by mistake.',
           de: 'Jemand wurde für einen schweren Kurs angenommen und hat ständig das Gefühl, versehentlich aufgenommen worden zu sein.' },
    q: { vi: 'Tôi đang ở đâu, tôi nên làm gì, và nếu cứ thế thì sẽ ra sao?',
         en: 'Where am I, what should I do, and what happens if this goes on?',
         de: 'Wo stehe ich, was soll ich tun, und was passiert, wenn das so weitergeht?' },
    model: { vi: 'Lá đầu là người mới học — đó là mô tả đúng, không phải lời chê. Lá giữa là những đêm nằm nhìn trần nhà, và ở vị trí lời khuyên thì nó không bảo người ta ngừng lo — nó bảo viết nỗi lo đó ra và xem cái nào có thật. Lá cuối là được công nhận công khai, thứ mà người này đang tin là sẽ không bao giờ tới.',
             en: 'The first card is a beginner — that is a description, not an insult. The middle is the nights staring at the ceiling, and in the advice seat it does not say stop worrying — it says write the worry down and see which parts are real. The last card is public recognition, the exact thing they are convinced will never come.',
             de: 'Die erste Karte ist eine Anfängerin — das ist eine Beschreibung, keine Beleidigung. Die mittlere sind die Nächte an der Zimmerdecke, und auf dem Ratsplatz sagt sie nicht: hör auf zu sorgen — sie sagt: schreib die Sorge auf und sieh, was davon real ist. Die letzte Karte ist öffentliche Anerkennung, genau das, wovon sie überzeugt ist, es werde nie kommen.' } },

  { id: 'pr-17', spread: 'tarot-yesno', free: false, course: 'tarot',
    cards: ['swords-7', 'cups-4', 'pentacles-5', 'major-15', 'wands-2'], rev: [1, 1, 0, 1, 0],
    frames: ['state', 'state', 'state', 'state', 'state'], traps: ['bare'],
    who: { vi: 'Một câu hỏi đóng, chỉ có hai khả năng trả lời.',
           en: 'A closed question with only two possible answers.',
           de: 'Eine geschlossene Frage mit nur zwei möglichen Antworten.' },
    q: { vi: 'Tôi có nên cho người bạn cũ vay số tiền đó không?',
         en: 'Should I lend that money to my old friend?',
         de: 'Soll ich diesem alten Freund das Geld leihen?' },
    model: { vi: 'Đếm trước: ba lá ngược, hai lá xuôi, nên câu trả lời là không. Nhưng một chữ “không” trơ trọi thì không phải một bài đọc. Lá giữa nói đây là cái “không” kiểu thiếu thốn chứ không phải kiểu ích kỷ, và lá ᡈn Chính trong hàng nói có một ràng buộc cũ khiến người hỏi khó từ chối.',
             en: 'Count first: three reversed against two upright, so the answer is no. But a bare no is not a reading. The middle card says this is a no of scarcity rather than a no of selfishness, and the Major in the row says an old tie is what makes refusing hard.',
             de: 'Erst zählen: drei umgekehrt gegen zwei aufrecht, also lautet die Antwort nein. Aber ein nacktes Nein ist keine Deutung. Die mittlere Karte sagt, dies ist ein Nein aus Knappheit, nicht aus Selbstsucht, und die Große Arkana in der Reihe sagt, eine alte Bindung macht das Ablehnen schwer.' } },

  { id: 'pr-18', spread: 'tarot-3', free: false, course: 'tarot',
    cards: ['wands-10', 'swords-4', 'major-20'], rev: [0, 0, 0], frames: ['state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một người làm hai công việc suốt một năm rưỡi. Gần đây sáng dậy thấy nặng ngực trước cả khi mở mắt.',
           en: 'Someone has worked two jobs for a year and a half. Lately the weight in their chest arrives before they open their eyes.',
           de: 'Jemand arbeitet seit anderthalb Jahren in zwei Jobs. In letzter Zeit ist die Schwere in der Brust schon da, bevor er die Augen öffnet.' },
    q: { vi: 'Tôi đang ở đâu, tôi nên làm gì, và nó sẽ dẫn tới đâu?',
         en: 'Where am I, what should I do, and where does this lead?',
         de: 'Wo stehe ich, was soll ich tun, und wohin führt das?' },
    model: { vi: 'Lá đầu là ôm quá nhiều gậy tới mức không còn nhìn thấy đường — không phải lười, mà là vác quá sức. Vị trí hai là lời khuyên và lá đó là nằm xuống: đây là một trong số ít trường hợp lời khuyên của bài là nghỉ, và nghỉ ở đây là việc phải làm chứ không phải phần thưởng. Lá cuối là một lần tính lại toàn bộ, không phải một lần cố thêm.',
             en: 'The first card is carrying so many staves you cannot see the road — not laziness, overload. Position two is advice and that card is lying down: this is one of the few times the reading’s advice is rest, and here rest is the work, not the reward. The last card is a full reckoning, not one more push.',
             de: 'Die erste Karte trägt so viele Stäbe, dass man den Weg nicht mehr sieht — keine Faulheit, Überlast. Position zwei ist ein Rat, und diese Karte liegt: Dies ist einer der seltenen Fälle, in denen der Rat der Legung Ruhe heißt, und Ruhe ist hier die Arbeit, nicht die Belohnung. Die letzte Karte ist eine vollständige Abrechnung, kein weiteres Durchhalten.' } },

  /* ---------------------------- Lenormand ----------------------------
     No reversals, and the pair is the unit: every model reading below reads
     the cards two at a time before it reads the row, because that is the
     habit the course spends its first lessons building. */
  { id: 'lp-1', spread: 'len-2', free: true, course: 'lenormand', deck: 'len',
    cards: [3, 34], rev: [0, 0], frames: ['state', 'state'], traps: [],
    who: { vi: 'Một chị bán đồ thủ công trên mạng vừa nhận được lời hỏi hàng từ một khách ở Hàn Quốc.',
           en: 'A woman who sells handmade goods online has just had an enquiry from a buyer in Korea.',
           de: 'Eine Frau, die online Handgemachtes verkauft, hat gerade eine Anfrage von einem Käufer aus Korea bekommen.' },
    q: { vi: 'Mối hàng này có đáng để tôi theo đuổi không?',
         en: 'Is this buyer worth pursuing?',
         de: 'Lohnt es sich, an diesem Kunden dranzubleiben?' },
    model: { vi: 'Con Thuyền cộng Con Cá gói lại thành một cụm: tiền đến từ phương xa, nói gọn là buôn bán với nước ngoài. Con Thuyền đứng trước nên nó là chủ đề, câu chuyện trước hết là chuyện khoảng cách và gửi hàng; Con Cá cho biết khoảng cách ấy sinh ra thu nhập. Câu trả lời là có, nhưng chị nên tính kỹ phí vận chuyển ngay từ đầu, vì với cặp bài này, đường xa chính là cái giá của đồng tiền.',
             en: 'Ship plus Fish reads as one phrase: money from far away — trade abroad, put simply. The Ship comes first, so it is the subject, and this is above all a story about distance and shipping; the Fish says that distance turns into income. The answer is yes, but she should work out the shipping costs from the start: with this pair, the long road is what the money costs.',
             de: 'Schiff und Fische ergeben zusammen einen Ausdruck: Geld aus der Ferne, kurz gesagt Handel mit dem Ausland. Das Schiff liegt vorn und ist damit das Thema, es geht also zuerst um Entfernung und Versand; die Fische sagen, dass aus dieser Entfernung Einkommen wird. Die Antwort lautet ja – aber sie sollte die Versandkosten von Anfang an durchrechnen, denn bei diesem Paar ist der weite Weg der Preis für das Geld.' } },

  { id: 'lp-2', spread: 'len-2', free: false, course: 'lenormand', deck: 'len',
    cards: [23, 4], rev: [0, 0], frames: ['state', 'state'], traps: [],
    who: { vi: 'Một cặp vợ chồng trẻ để dành mua nhà đã hai năm, nhưng số dư cứ vơi dần mà không ai nói được vì sao.',
           en: 'A young couple have been saving for a flat for two years, but the balance keeps shrinking and neither of them can say why.',
           de: 'Ein junges Paar spart seit zwei Jahren auf eine Wohnung, doch das Konto schrumpft, und keiner der beiden weiß genau, warum.' },
    q: { vi: 'Tiền để dành mua nhà của chúng tôi đang đi đâu?',
         en: 'Where is our money for the flat going?',
         de: 'Wohin verschwindet das Geld für unsere Wohnung?' },
    model: { vi: 'Đàn Chuột đứng trước nên nó là chủ đề: một sự hao hụt nhỏ nhưng đều đặn, kiểu gặm nhấm từng chút chứ không phải một cú mất lớn. Ngôi Nhà bổ nghĩa cho nó: chỗ rò nằm ngay trong chi tiêu của gia đình, không phải một tai hoạ từ bên ngoài. Tin tốt là Đàn Chuột dừng lại ngay khi bị nhìn thấy: ghi lại mọi khoản chi trong một tháng là đủ để tìm ra thủ phạm.',
             en: 'The Mice come first, so they are the subject: a small, steady loss — the kind that nibbles rather than bites. The House describes it: the leak is inside the household’s own spending, not a blow from outside. The good news is that the Mice stop the moment they are seen: writing down every expense for one month is enough to find the culprit.',
             de: 'Die Mäuse liegen vorn, sie sind also das Thema: ein kleiner, stetiger Verlust, der nagt, statt zuzubeißen. Das Haus beschreibt ihn näher: Das Leck steckt in den eigenen Haushaltsausgaben, nicht in einem Schlag von außen. Die gute Nachricht: Die Mäuse hören auf, sobald man sie sieht. Einen Monat lang jede Ausgabe aufzuschreiben reicht, um den Übeltäter zu finden.' } },

  { id: 'lp-3', spread: 'len-3', free: false, course: 'lenormand', deck: 'len',
    cards: [28, 6, 25], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Một cô gái 29 tuổi yêu anh bạn trai đã bốn năm. Cứ mỗi lần cô nhắc đến chuyện cưới, anh lại lảng sang chuyện khác.',
           en: 'A woman of 29 has been with her boyfriend for four years. Whenever she mentions marriage, he changes the subject.',
           de: 'Eine 29-Jährige ist seit vier Jahren mit ihrem Freund zusammen. Sobald sie das Thema Heirat anspricht, lenkt er ab.' },
    q: { vi: 'Anh ấy thật sự nghĩ gì về chuyện cưới xin?',
         en: 'What does he really think about marriage?',
         de: 'Was denkt er wirklich über eine Heirat?' },
    model: { vi: 'Người Đàn Ông mở đầu hàng bài, nên đây là chuyện của anh ấy chứ không phải của cô. Mây ở giữa là trọng tâm: trong đầu anh đang mù mờ, chưa rõ mình muốn gì; đọc thành cặp với Người Đàn Ông, đó là một người đang bối rối chứ không phải một người đang từ chối. Mây cộng Chiếc Nhẫn là một lời cam kết tạm thời bị che khuất. Mây rồi sẽ tan, nên câu trả lời không phải là "không", mà là "anh ấy chưa nhìn rõ".',
             en: 'The Man opens the row, so this is his story, not hers. The Clouds in the middle carry the weight: his mind is hazy and he does not yet know what he wants; read as a pair with the Man, this is a confused man, not a refusing one. Clouds plus Ring is a commitment hidden from view for now. Clouds pass, so the answer is not “no” but “not yet clear to him”.',
             de: 'Der Herr eröffnet die Reihe, es geht also um ihn, nicht um sie. Die Wolken in der Mitte tragen das Gewicht: In seinem Kopf ist es neblig, er weiß noch nicht, was er will; als Paar mit dem Herrn gelesen ist das ein verunsicherter Mann, kein ablehnender. Wolken und Ring zeigen eine Bindung, die vorerst verdeckt ist. Wolken ziehen weiter – die Antwort lautet also nicht „nein“, sondern „für ihn noch nicht klar“.' } },

  { id: 'lp-4', spread: 'len-3', free: false, course: 'lenormand', deck: 'len',
    cards: [14, 15, 33], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Một nhân viên văn phòng nghi rằng đồng nghiệp đang nhận công dự án của mình trước mặt sếp.',
           en: 'An office worker suspects a colleague is taking credit for her project in front of the boss.',
           de: 'Eine Büroangestellte hat den Verdacht, dass sich ein Kollege vor dem Chef mit ihrem Projekt schmückt.' },
    q: { vi: 'Tôi nên xử lý chuyện này thế nào?',
         en: 'How should I handle this?',
         de: 'Wie soll ich damit umgehen?' },
    model: { vi: 'Con Cáo mở đầu: chuyện xảy ra ở nơi làm việc, và có một người đang tính toán để tự bảo vệ mình. Con Gấu ở giữa là trọng tâm: người nắm quyền, tức là sếp, đang giữ chìa khoá của câu chuyện; Cáo cộng Gấu là một chiến lược nhắm thẳng vào người có quyền. Gấu cộng Chìa Khoá chỉ ra hướng đi rõ ràng: lời giải là tự tay đưa kết quả của mình tới sếp, bằng số liệu và bằng văn bản, trước khi người khác kể thay mình.',
             en: 'The Fox opens: this is about the workplace, and someone is calculating to protect themselves. The Bear in the middle is the heart of it: the person with power — the boss — holds the story; Fox plus Bear is a strategy aimed straight at authority. Bear plus Key points the way: the solution is to put her results into the boss’s hands herself, with figures and in writing, before someone else tells the story for her.',
             de: 'Der Fuchs eröffnet: Es geht um den Arbeitsplatz, und jemand taktiert, um sich selbst zu schützen. Der Bär in der Mitte ist der Kern: Die Person mit Macht – der Chef – hat die Geschichte in der Hand; Fuchs und Bär sind eine Strategie, die direkt auf die Autorität zielt. Bär und Schlüssel zeigen den Weg: Die Lösung ist, die eigenen Ergebnisse selbst beim Chef abzuliefern, mit Zahlen und schriftlich, bevor jemand anderes die Geschichte erzählt.' } },

  { id: 'lp-5', spread: 'len-3', free: false, course: 'lenormand', deck: 'len',
    cards: [12, 18, 9], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Hai cô bạn thân từ thời đại học cãi nhau qua tin nhắn và đã lâu rồi không nói chuyện với nhau.',
           en: 'Two friends since university fell out over text messages and have not spoken since.',
           de: 'Zwei Freundinnen seit der Studienzeit haben sich per Nachricht zerstritten und seitdem kein Wort gewechselt.' },
    q: { vi: 'Tình bạn của chúng tôi có hàn gắn được không?',
         en: 'Can our friendship be mended?',
         de: 'Lässt sich unsere Freundschaft wieder kitten?' },
    model: { vi: 'Đôi Chim mở đầu: gốc của chuyện là lời nói, và lối ra cũng là lời nói, lần này là một cuộc gọi hay một buổi gặp chứ không phải tin nhắn. Con Chó ở giữa là trọng tâm: đây là một tình bạn trung thành và lâu năm, không phải một mối quen sơ. Chó cộng Bó Hoa mở ra một hướng đi dịu dàng: một lời mời hay một món quà nhỏ sẽ nối lại được, và người mở lời trước sẽ được đón nhận.',
             en: 'The Birds open: this began with words, and words are also the way out — a call or a meeting this time, not a text. The Dog in the middle is the heart of it: a loyal, long-standing friendship, not a passing acquaintance. Dog plus Bouquet opens a gentle road: an invitation or a small gift will mend it, and whoever reaches out first will be welcomed.',
             de: 'Die Vögel eröffnen: Angefangen hat es mit Worten, und Worte sind auch der Ausweg – diesmal ein Anruf oder ein Treffen statt einer Nachricht. Der Hund in der Mitte ist der Kern: eine treue, gewachsene Freundschaft, keine flüchtige Bekanntschaft. Hund und Blumenstrauß weisen einen freundlichen Weg: Eine Einladung oder ein kleines Geschenk wird die Sache kitten, und wer sich zuerst meldet, wird mit offenen Armen empfangen.' } },

  { id: 'lp-6', spread: 'len-3', free: false, course: 'lenormand', deck: 'len',
    cards: [4, 17, 31], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: ['bare'],
    who: { vi: 'Một gia đình ba người được mời thuê một căn nhà rộng hơn ở ngoại ô, xa chỗ làm của người chồng hơn.',
           en: 'A family of three has been offered a bigger house to rent on the edge of town, further from the husband’s work.',
           de: 'Einer dreiköpfigen Familie wird ein größeres Haus am Stadtrand zur Miete angeboten, weiter weg von der Arbeit des Mannes.' },
    q: { vi: 'Chúng tôi có nên chuyển nhà không?',
         en: 'Should we move?',
         de: 'Sollen wir umziehen?' },
    model: { vi: 'Ngôi Nhà mở đầu, nên câu hỏi đã nằm đúng chỗ: đây là chuyện mái ấm. Con Cò ở giữa là trọng tâm, và Cò chính là lá của việc chuyển chỗ và đổi đời theo hướng tốt; Nhà cộng Cò đọc gọn là "dọn sang nhà mới để sống tốt hơn". Mặt Trời ở cuối là một trong những lá "có" mạnh nhất: câu trả lời là có, một cái có ấm áp chứ không miễn cưỡng. Nhưng đừng dừng ở chữ "có": hãy nói có vì đâu.',
             en: 'The House opens, so the question sits in the right place: this is about home. The Stork in the middle carries the weight, and the Stork is the card of moving and of change for the better; House plus Stork reads simply as “moving to a new home to live better”. The Sun at the end is one of the strongest yes cards: the answer is yes, and a warm one, not a grudging one. But do not stop at the word yes — say why.',
             de: 'Das Haus eröffnet, die Frage liegt also am richtigen Ort: Es geht ums Zuhause. Der Storch in der Mitte trägt das Gewicht, und er ist die Karte für Umzug und Veränderung zum Besseren; Haus und Storch heißt schlicht: „in ein neues Zuhause ziehen, um besser zu leben“. Die Sonne am Ende ist eine der stärksten Ja-Karten: Die Antwort ist ja, und zwar ein herzliches, kein widerwilliges. Aber bleib nicht beim Wort „ja“ stehen – sag, warum.' } },

  { id: 'lp-7', spread: 'len-5', free: false, course: 'lenormand', deck: 'len',
    cards: [26, 13, 11, 20, 16], rev: [0, 0, 0, 0, 0], frames: ['state', 'state', 'state', 'outcome', 'outcome'], traps: [],
    who: { vi: 'Một cô giáo dạy vẽ muốn mở lớp học trực tuyến đầu tiên của mình, nhưng cô chưa từng đứng trước máy quay.',
           en: 'An art teacher wants to launch her first online class, but she has never stood in front of a camera.',
           de: 'Eine Zeichenlehrerin möchte ihren ersten Onlinekurs starten, hat aber noch nie vor einer Kamera gestanden.' },
    q: { vi: 'Lớp học trực tuyến này sẽ đi tới đâu?',
         en: 'Where will this online class take me?',
         de: 'Wohin führt mich dieser Onlinekurs?' },
    model: { vi: 'Cuốn Sách ở bối cảnh cho biết vốn liếng của cô là chuyên môn thật, thứ cô đã tích luỹ nhiều năm. Đứa Trẻ đang hình thành: một khởi đầu mới, còn non, và được phép vụng về. Ngọn Roi ở trung tâm là cốt lõi: thành bại không nằm ở tài năng mà ở kỷ luật, ở việc quay hết buổi này đến buổi khác cho tới khi quen tay; Trẻ cộng Roi là một người mới tập nhưng tập đều. Roi cộng Khu Vườn cho thấy chính sự lặp lại ấy đưa cô ra trước công chúng, và Những Vì Sao ở kết quả hứa một con đường rõ ràng, với rất nhiều người theo dõi nếu cô giữ được nhịp.',
             en: 'The Book in the background says her capital is real expertise, built up over years. The Child is forming: a new beginning, still young and allowed to be clumsy. The Whip at the centre is the core: success will come not from talent but from discipline — filming session after session until it feels natural; Child plus Whip is a beginner who practises steadily. Whip plus Garden shows that very repetition carrying her out in front of the public, and the Stars as the outcome promise a clear path, with many people following if she keeps the rhythm.',
             de: 'Das Buch im Hintergrund sagt, dass ihr Kapital echte Fachkenntnis ist, über Jahre aufgebaut. Das Kind ist im Entstehen: ein Neuanfang, noch jung, der ungeschickt sein darf. Die Rute in der Mitte ist der Kern: Der Erfolg hängt nicht vom Talent ab, sondern von Disziplin – davon, Folge um Folge zu drehen, bis es sich selbstverständlich anfühlt; Kind und Rute sind eine Anfängerin, die regelmäßig übt. Rute und Park zeigen, wie genau diese Wiederholung sie in die Öffentlichkeit bringt, und die Sterne als Ergebnis versprechen einen klaren Weg, mit vielen, die ihr folgen, wenn sie den Rhythmus hält.' } },

  { id: 'lp-8', spread: 'len-3', free: false, course: 'lenormand', deck: 'len',
    cards: [29, 22, 36], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Một kế toán 38 tuổi đã gắn bó với một công ty suốt mười năm. Một startup mời cô về, lương thấp hơn nhưng là công việc cô thích hơn.',
           en: 'An accountant of 38 has been with the same firm for ten years. A startup has offered her a job — lower pay, but work she would enjoy more.',
           de: 'Eine 38-jährige Buchhalterin arbeitet seit zehn Jahren in derselben Firma. Ein Start-up bietet ihr eine Stelle an – weniger Gehalt, aber eine Arbeit, die ihr mehr liegt.' },
    q: { vi: 'Tôi đang đứng ở đâu trong lựa chọn này?',
         en: 'Where do I stand in this choice?',
         de: 'Wo stehe ich bei dieser Entscheidung?' },
    model: { vi: 'Người Phụ Nữ mở đầu: đây là chuyện của chính cô, không phải chuyện của công ty nào. Ngã Rẽ ở giữa là trọng tâm: cô thật sự có hai lựa chọn và có quyền chọn; Phụ Nữ cộng Ngã Rẽ là một người phụ nữ được tự do quyết định, chứ không phải bị dồn vào thế. Ngã Rẽ cộng Cây Thánh Giá cho biết quyết định này nặng lòng, nhưng Thánh Giá ở cuối cũng là lá của gánh nặng sắp qua: dù cô chọn đường nào, giai đoạn giằng co sẽ khép lại khi cô chọn theo điều mình thấy có ý nghĩa.',
             en: 'The Woman opens: this is her own story, not the company’s. The Crossroads in the middle is the heart of it: she really does have two options, and the freedom to choose; Woman plus Crossroads is a woman free to decide, not one who has been cornered. Crossroads plus Cross says the decision weighs on her, but the Cross at the end is also the card of a burden nearly carried: whichever road she takes, the tug-of-war will end once she chooses by what feels meaningful to her.',
             de: 'Die Dame eröffnet: Es geht um sie selbst, nicht um irgendeine Firma. Die Wege in der Mitte sind der Kern: Sie hat wirklich zwei Möglichkeiten und die Freiheit zu wählen; Dame und Wege zeigen eine Frau, die frei entscheiden kann, nicht eine, die in die Enge getrieben wurde. Wege und Kreuz sagen, dass die Entscheidung schwer wiegt, doch das Kreuz am Ende ist auch die Karte der Last, die fast getragen ist: Welchen Weg sie auch nimmt, das Hin und Her endet, sobald sie nach dem wählt, was ihr sinnvoll erscheint.' } },

  /* --------------------------- playing cards ---------------------------
     Upright only, and the suit carries the theme: Hearts feeling, Diamonds
     money, Clubs work and friends, Spades trouble. The model readings name
     the suit pattern of the row as well as each card, because a run of one
     suit is the first thing a card reader notices. */
  { id: 'pp-1', spread: 'pc-3', free: true, course: 'playing', deck: 'pc',
    cards: ['h6', 'c9', 'h2'], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Một chàng trai 27 tuổi vừa nhận được tin nhắn hỏi thăm của người yêu cũ sau hai năm chia tay. Anh đang có cảm tình với một cô gái mới quen.',
           en: 'A man of 27 has just heard from his ex, two years after they split. He is already drawn to someone new.',
           de: 'Ein 27-Jähriger hat nach zwei Jahren Funkstille eine Nachricht von seiner Ex bekommen. Dabei hat er gerade Gefühle für eine neue Bekanntschaft.' },
    q: { vi: 'Tin nhắn này có ý nghĩa gì với chuyện tình cảm của tôi?',
         en: 'What does this message mean for my love life?',
         de: 'Was bedeutet diese Nachricht für mein Liebesleben?' },
    model: { vi: '6 Cơ ở quá khứ là lá của kỷ niệm và người cũ quay lại: tin nhắn kia đến từ ký ức nhiều hơn là từ một tình cảm mới. 9 Chuồn ở hiện tại cho thấy trong lòng anh đã có một mối tình mới đang nhen nhóm, và nó cũng báo trước một chút bất đồng với bạn bè quanh chuyện này. 2 Cơ ở tương lai là một đôi lứa có tình cảm được đáp lại; đi sau 9 Chuồn, đôi ấy nhiều khả năng là anh và cô gái mới, nếu anh không để quá khứ chen vào hiện tại.',
             en: 'The 6 of Hearts in the past is the card of memories and of someone returning: that message comes from nostalgia more than from new feeling. The 9 of Clubs in the present shows a new romance already kindling in his heart — and warns of a little disagreement with friends about it. The 2 of Hearts in the future is a couple whose love is returned; coming after the 9 of Clubs, that couple is most likely him and the new person, if he does not let the past crowd into the present.',
             de: 'Die Herz Sechs in der Vergangenheit ist die Karte der Erinnerungen und der Menschen, die zurückkehren: Die Nachricht kommt eher aus Nostalgie als aus neuem Gefühl. Die Kreuz Neun in der Gegenwart zeigt, dass in seinem Herzen schon eine neue Romanze aufkeimt – und kündigt etwas Streit mit Freunden darüber an. Die Herz Zwei in der Zukunft ist ein Paar mit erwiderten Gefühlen; nach der Kreuz Neun sind das sehr wahrscheinlich er und die neue Bekanntschaft, wenn er die Vergangenheit nicht in die Gegenwart drängen lässt.' } },

  { id: 'pp-2', spread: 'pc-3', free: false, course: 'playing', deck: 'pc',
    cards: ['d7', 'd3', 'd4'], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Hai anh em cùng góp vốn mở quán cà phê của gia đình. Dạo này họ cãi nhau vì chuyện sổ sách, và họ hàng bắt đầu bàn tán.',
           en: 'Two brothers put money into the family café together. Lately they have been arguing over the books, and the relatives have started to talk.',
           de: 'Zwei Brüder haben gemeinsam Geld in das Familiencafé gesteckt. In letzter Zeit streiten sie über die Buchhaltung, und in der Verwandtschaft wird schon getuschelt.' },
    q: { vi: 'Chuyện làm ăn chung của hai anh em tôi sẽ đi về đâu?',
         en: 'Where is our shared business heading?',
         de: 'Wohin steuert unser gemeinsames Geschäft?' },
    model: { vi: '7 Rô ở quá khứ là lời đàm tiếu và nỗi lo tiền bạc: chuyện bắt đầu từ những lời ra tiếng vào và một khoản hụt nhỏ, chứ chưa phải từ một sự phản bội. 3 Rô ở hiện tại là giấy tờ và cãi vã trong nhà: vấn đề thật nằm ở sổ sách, và nó cần được giải quyết bằng giấy trắng mực đen chứ không bằng lời qua tiếng lại. 4 Rô ở tương lai là tiền bạc ổn định và sự an toàn: nếu hai anh em ngồi lại làm sổ sách cho rõ ràng, quán sẽ đứng vững. Cả ba lá đều là Rô, nghĩa là đây là chuyện tiền, không phải chuyện tình thân.',
             en: 'The 7 of Diamonds in the past is gossip and money worries: this started with talk and a small shortfall, not with betrayal. The 3 of Diamonds in the present is paperwork and quarrels at home: the real problem sits in the books, and it needs settling in black and white, not in back-and-forth. The 4 of Diamonds in the future is steady money and security: if the brothers sit down and put the accounts in order, the café will stand. All three cards are Diamonds — this is about money, not about family love.',
             de: 'Die Karo Sieben in der Vergangenheit steht für Gerede und Geldsorgen: Angefangen hat es mit Getuschel und einem kleinen Fehlbetrag, nicht mit Verrat. Die Karo Drei in der Gegenwart steht für Unterlagen und Streit zuhause: Das eigentliche Problem liegt in der Buchhaltung, und es muss schwarz auf weiß gelöst werden, nicht im Hin und Her. Die Karo Vier in der Zukunft steht für beständige Finanzen und Sicherheit: Wenn die Brüder sich zusammensetzen und die Bücher ordnen, hat das Café Bestand. Alle drei Karten sind Karo – hier geht es um Geld, nicht um die Liebe in der Familie.' } },

  { id: 'pp-3', spread: 'pc-3', free: false, course: 'playing', deck: 'pc',
    cards: ['c8', 's4', 'c10'], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: ['bare'],
    who: { vi: 'Một nữ kỹ sư phần mềm làm thêm giờ liên tục suốt nửa năm để kịp dự án. Giờ cô ngủ không ngon và hay cáu gắt.',
           en: 'A software engineer has worked overtime for half a year to hit a deadline. Now she sleeps badly and snaps easily.',
           de: 'Eine Softwareentwicklerin macht seit einem halben Jahr ständig Überstunden, um eine Deadline zu halten. Jetzt schläft sie schlecht und ist schnell gereizt.' },
    q: { vi: 'Tôi có nên xin nghỉ một thời gian không?',
         en: 'Should I take some time off?',
         de: 'Sollte ich mir eine Auszeit nehmen?' },
    model: { vi: '8 Chuồn ở quá khứ gọi đúng tên chuyện đã xảy ra: làm việc quá sức, như thể đem sức khoẻ ra đặt cược để lấy tiến độ. 4 Bích ở hiện tại là một bước chững lại, và bản thân lá bài đã là lời khuyên: nghỉ và hồi sức trước khi đi tiếp. 10 Chuồn ở tương lai là thành công trong công việc và may mắn đến sau nỗ lực, tức là kỳ nghỉ không lấy đi thành quả nào của cô mà còn giúp cô về đích. Câu trả lời là có, và nên nghỉ ngay bây giờ, đừng đợi đến lúc kiệt sức.',
             en: 'The 8 of Clubs in the past names what happened: overwork, as if she had staked her health against the deadline. The 4 of Spades in the present is a pause, and the card is its own advice: rest and recover before moving on. The 10 of Clubs in the future is success at work and luck that follows effort — the break takes nothing she has built; it carries her to the finish. The answer is yes, and now, not after she burns out.',
             de: 'Die Kreuz Acht in der Vergangenheit benennt, was passiert ist: Überarbeitung, als hätte sie ihre Gesundheit gegen die Deadline gesetzt. Die Pik Vier in der Gegenwart ist eine Pause, und die Karte ist selbst schon der Rat: ausruhen und zu Kräften kommen, bevor es weitergeht. Die Kreuz Zehn in der Zukunft steht für beruflichen Erfolg und Glück nach eigener Anstrengung – die Auszeit nimmt ihr nichts von dem, was sie aufgebaut hat, sondern trägt sie ins Ziel. Die Antwort ist ja, und zwar jetzt, nicht erst nach dem Burn-out.' } },

  { id: 'pp-4', spread: 'pc-3', free: false, course: 'playing', deck: 'pc',
    cards: ['sJ', 's7', 'cJ'], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Một chủ tiệm tạp hoá vừa nhận một cậu nhân viên trẻ rất nhanh nhảu. Mới hai tuần mà tiền trong két đã hai lần bị thiếu.',
           en: 'A corner-shop owner has just taken on a very quick young assistant. In two weeks the till has come up short twice.',
           de: 'Ein Ladenbesitzer hat gerade eine sehr flinke junge Aushilfe eingestellt. In zwei Wochen hat schon zweimal Geld in der Kasse gefehlt.' },
    q: { vi: 'Tôi có nên tin người này không?',
         en: 'Should I trust this person?',
         de: 'Kann ich diesem Menschen vertrauen?' },
    model: { vi: 'J Bích ở quá khứ là một người trẻ không đáng tin, thậm chí là một đối thủ: ngay từ đầu đã có điều gì đó không ổn. 7 Bích ở hiện tại là mất mát và lời cảnh báo đừng tin người quá dễ: hai lần thiếu tiền không phải là trùng hợp. J Chuồn ở tương lai là một người bạn đáng tin, một chàng trai chân thành: người ông chủ cần là một người khác, hoặc là người được kiểm tra kỹ trước khi giao chìa khoá két. Hai lá J đứng ở hai đầu cho thấy đây là chuyện chọn người, còn chất Bích nói rằng người hiện tại chưa phải là người đó.',
             en: 'The Jack of Spades in the past is an untrustworthy young person, even a rival: something was off from the start. The 7 of Spades in the present is a loss and a warning not to trust too easily: two short tills are not a coincidence. The Jack of Clubs in the future is a reliable friend, a sincere young man: the helper this shop needs is someone else, or someone checked properly before being handed the key to the till. Two Jacks at either end make this a story about choosing people, and the Spades say the present choice is not the right one.',
             de: 'Der Pik Bube in der Vergangenheit ist ein unzuverlässiger junger Mensch, vielleicht sogar ein Konkurrent: Von Anfang an stimmte etwas nicht. Die Pik Sieben in der Gegenwart steht für Verlust und die Warnung, Vertrauen nicht vorschnell zu schenken: Zweimal fehlendes Geld ist kein Zufall. Der Kreuz Bube in der Zukunft ist ein verlässlicher Freund, ein aufrichtiger junger Mensch: Die Hilfe, die der Laden braucht, ist jemand anderes – oder jemand, der gründlich geprüft wird, bevor er den Kassenschlüssel bekommt. Zwei Buben an beiden Enden machen daraus eine Geschichte über die Wahl von Menschen, und das Pik sagt: Die jetzige Wahl ist nicht die richtige.' } },

  { id: 'pp-5', spread: 'pc-3', free: false, course: 'playing', deck: 'pc',
    cards: ['dA', 'd5', 'd10'], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: [],
    who: { vi: 'Một nữ điều dưỡng 30 tuổi vừa nhận được email mời phỏng vấn cho một vị trí làm việc ở Đức.',
           en: 'A nurse of 30 has just received an email inviting her to interview for a job in Germany.',
           de: 'Eine 30-jährige Pflegekraft hat gerade per E-Mail eine Einladung zum Vorstellungsgespräch für eine Stelle in Deutschland bekommen.' },
    q: { vi: 'Cơ hội này sẽ mang lại cho tôi điều gì?',
         en: 'What will this opportunity bring me?',
         de: 'Was wird mir diese Chance bringen?' },
    model: { vi: 'Át Rô ở quá khứ là thư từ, tin nhắn và tin về tiền bạc: chính lá email kia là hạt giống của cả câu chuyện. 5 Rô ở hiện tại là tin vui và thay đổi theo hướng tốt: cô đang đứng trước ngưỡng cửa của một bước tiến thật sự. 10 Rô ở tương lai là tiền bạc và một chuyến đi xa, đúng với một công việc ở nước ngoài có thu nhập khá hơn. Ba lá Rô nối nhau từ Át lên Mười là chất Rô đi trọn một vòng: từ một lá thư đến một cuộc sống vật chất đủ đầy.',
             en: 'The Ace of Diamonds in the past is a letter, a message, news about money: that very email is the seed of the whole story. The 5 of Diamonds in the present is good news and a change for the better: she stands at the threshold of real progress. The 10 of Diamonds in the future is money and a long journey — exactly what a better-paid job abroad looks like. Three Diamonds climbing from Ace to Ten is the suit running its full course: from a single letter to a secure, well-provided life.',
             de: 'Das Karo Ass in der Vergangenheit steht für Brief, Nachricht und Neuigkeiten über Geld: Genau diese E-Mail ist der Samen der ganzen Geschichte. Die Karo Fünf in der Gegenwart steht für gute Nachrichten und eine Wendung zum Besseren: Sie steht an der Schwelle zu einem echten Fortschritt. Die Karo Zehn in der Zukunft steht für Geld und eine weite Reise – genau so sieht eine besser bezahlte Stelle im Ausland aus. Drei Karos, die vom Ass bis zur Zehn aufsteigen, sind die Farbe, die ihren ganzen Weg geht: von einem einzigen Brief bis zu einem sicheren, gut versorgten Leben.' } },

  { id: 'pp-6', spread: 'pc-5', free: false, course: 'playing', deck: 'pc',
    cards: ['hA', 's2', 'd2', 'hK', 'c3'], rev: [0, 0, 0, 0, 0], frames: ['state', 'state', 'state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một cặp vợ chồng cưới nhau được ba năm, dạo này cãi nhau liên tục vì chuyện tiền. Người vợ đang tính chuyện ly thân một thời gian.',
           en: 'A couple married three years keep fighting about money. The wife is thinking about a trial separation.',
           de: 'Ein Paar, seit drei Jahren verheiratet, streitet ständig über Geld. Die Frau denkt über eine Trennung auf Zeit nach.' },
    q: { vi: 'Cuộc hôn nhân của chúng tôi còn cứu được không, và tôi nên làm gì?',
         en: 'Can our marriage be saved, and what should I do?',
         de: 'Ist unsere Ehe noch zu retten, und was soll ich tun?' },
    model: { vi: 'Át Cơ ở quá khứ là mái nhà và niềm vui gia đình: nền móng của cuộc hôn nhân này là tình yêu thật. 2 Bích ở hiện tại là chia ly, một khoảng tạm dừng và một lựa chọn khó: ý định ly thân đúng là điều đang diễn ra. 2 Rô ở vị trí cản trở gọi tên thủ phạm: bất đồng về tiền và cảm giác phải chọn một trong hai. K Cơ ở lời khuyên là một người đàn ông ấm áp, rộng lượng và một lời khuyên tốt: hãy tìm đến một người như thế, có thể chính người chồng khi được mời nói thật lòng, có thể là một người đi trước đáng tin, để cùng ngồi lại bàn chuyện tiền. 3 Chuồn ở kết quả là hôn nhân, sự gắn bó lâu dài và cơ hội thứ hai: cuộc hôn nhân này cứu được, nếu hai người coi tiền bạc là việc cùng làm chứ không phải một chiến trường.',
             en: 'The Ace of Hearts in the past is home and family happiness: this marriage was built on real love. The 2 of Spades in the present is separation, a pause and a hard choice: the thought of separating is exactly what is going on. The 2 of Diamonds in the blocking position names the culprit: disagreement over money, and the feeling of having to choose one side. The King of Hearts as advice is a warm, generous man and good counsel: she should turn to someone like that — perhaps her husband himself, once invited to speak honestly, perhaps a trusted older friend — and sit down together about money. The 3 of Clubs as the outcome is marriage, a long partnership and a second chance: this marriage can be saved, if the two of them treat money as shared work rather than a battlefield.',
             de: 'Das Herz Ass in der Vergangenheit steht für Zuhause und Familienglück: Diese Ehe wurde auf echter Liebe gebaut. Die Pik Zwei in der Gegenwart steht für Trennung, eine Pause und eine schwierige Wahl: Der Gedanke an eine Trennung ist genau das, was gerade geschieht. Die Karo Zwei an der Stelle des Hindernisses benennt den Übeltäter: Streit ums Geld und das Gefühl, sich für eine Seite entscheiden zu müssen. Der Herz König als Rat ist ein warmer, großzügiger Mann und ein guter Ratschlag: Sie sollte sich an so jemanden wenden – vielleicht an ihren Mann selbst, wenn er eingeladen wird, offen zu reden, vielleicht an eine erfahrene Vertrauensperson – und sich gemeinsam ans Thema Geld setzen. Die Kreuz Drei als Ergebnis steht für Ehe, langfristige Partnerschaft und eine zweite Chance: Diese Ehe ist zu retten, wenn die beiden Geld als gemeinsame Aufgabe sehen und nicht als Schlachtfeld.' } },

  { id: 'pp-7', spread: 'pc-3', free: false, course: 'playing', deck: 'pc',
    cards: ['h7', 'cA', 'h9'], rev: [0, 0, 0], frames: ['state', 'state', 'outcome'], traps: ['bare'],
    who: { vi: 'Một nữ sinh trượt nguyện vọng một năm ngoái và vừa thi lại vào ngành kiến trúc.',
           en: 'A student missed out on her first-choice university last year and has just sat the architecture entrance exam again.',
           de: 'Eine Schülerin hat letztes Jahr ihren Wunschstudienplatz verpasst und gerade noch einmal die Aufnahmeprüfung für Architektur geschrieben.' },
    q: { vi: 'Lần này tôi có đỗ không?',
         en: 'Will I get in this time?',
         de: 'Schaffe ich es diesmal?' },
    model: { vi: '7 Cơ ở quá khứ là thất vọng và lời hứa không thành: lần trượt năm ngoái vẫn còn để lại dư vị. Át Chuồn ở hiện tại là thành công và một khởi đầu tốt: lần này cô bước vào với nền tảng vững vàng hơn. 9 Cơ ở tương lai là lá ước nguyện, điều mong muốn thành hiện thực, một trong những lá "có" rõ ràng nhất của bộ bài Tây. Câu trả lời là có, và đó là cái có được xây nên từ chính nỗ lực của cả năm vừa qua.',
             en: 'The 7 of Hearts in the past is disappointment and a promise not kept: last year’s miss still leaves an aftertaste. The Ace of Clubs in the present is success and a good beginning: this time she comes in on firmer ground. The 9 of Hearts in the future is the wish card — what you hope for comes true — one of the clearest yes cards in the pack. The answer is yes, and it is a yes built from a whole year of her own effort.',
             de: 'Die Herz Sieben in der Vergangenheit steht für Enttäuschung und ein nicht gehaltenes Versprechen: Die Absage vom letzten Jahr wirkt noch nach. Das Kreuz Ass in der Gegenwart steht für Erfolg und einen guten Anfang: Diesmal geht sie mit einem festeren Fundament hinein. Die Herz Neun in der Zukunft ist die Wunschkarte – ein Herzenswunsch findet Erfüllung – und eine der klarsten Ja-Karten des Blatts. Die Antwort ist ja, und dieses Ja ist aus einem ganzen Jahr eigener Arbeit gebaut.' } },

  { id: 'pp-8', spread: 'pc-5', free: false, course: 'playing', deck: 'pc',
    cards: ['s10', 'c4', 's6', 'cK', 'c6'], rev: [0, 0, 0, 0, 0], frames: ['state', 'state', 'state', 'advice', 'outcome'], traps: [],
    who: { vi: 'Một anh thợ may vừa trải qua một năm thua lỗ vì mất khách hàng lớn nhất. Anh đang cân nhắc vay thêm tiền để làm lại từ đầu.',
           en: 'A tailor has come through a year of losses after losing his biggest client. He is weighing whether to borrow more and start again.',
           de: 'Ein Schneider hat ein Verlustjahr hinter sich, weil ihm sein größter Kunde weggebrochen ist. Jetzt überlegt er, noch einmal einen Kredit aufzunehmen und neu anzufangen.' },
    q: { vi: 'Nếu làm lại, việc làm ăn của tôi sẽ ra sao?',
         en: 'What happens to my business if I start again?',
         de: 'Wie geht es mit meinem Geschäft weiter, wenn ich neu anfange?' },
    model: { vi: '10 Bích ở quá khứ là lo âu, cảm giác bị trói buộc, nhưng cũng là một giai đoạn khó đang khép lại: năm tệ nhất đã ở sau lưng. 4 Chuồn ở hiện tại là thay đổi và vận rủi bất ngờ, kèm lời nhắc tránh xung đột: đừng dồn sức vào việc giành lại khách cũ. 6 Bích ở vị trí cản trở là một tiến bộ nhỏ và một chuyến đi để bỏ lại rắc rối: thứ đang cản anh chính là nỗi e ngại bước ra khỏi chuyện cũ. K Chuồn ở lời khuyên là một người đàn ông rộng rãi, trung thành, một người cố vấn tốt: trước khi vay, hãy hỏi ý một người từng làm ăn mà anh tin được. 6 Chuồn ở kết quả là làm ăn thuận lợi và được hỗ trợ tài chính: có người cố vấn ấy bên cạnh, việc làm lại sẽ thành.',
             en: 'The 10 of Spades in the past is anxiety and feeling trapped, but also a hard period coming to a close: the worst year is behind him. The 4 of Clubs in the present is change and sudden misfortune, with a reminder to avoid conflict: he should not pour his strength into winning the old client back. The 6 of Spades in the blocking position is small progress and a journey to leave trouble behind: what holds him back is his reluctance to step away from the old story. The King of Clubs as advice is a generous, loyal man, a good adviser: before borrowing, he should ask someone with business experience whom he trusts. The 6 of Clubs as the outcome is business success and financial support: with that adviser beside him, starting again will work.',
             de: 'Die Pik Zehn in der Vergangenheit steht für Sorge und ein Gefühl von Enge, aber auch für eine schwierige Phase, die zu Ende geht: Das schlimmste Jahr liegt hinter ihm. Die Kreuz Vier in der Gegenwart steht für Veränderung und unerwartetes Pech, verbunden mit der Mahnung, Konflikte nicht anzuheizen: Er sollte seine Kraft nicht darauf verwenden, den alten Kunden zurückzugewinnen. Die Pik Sechs an der Stelle des Hindernisses steht für kleine Fortschritte und eine Reise, um Schwierigkeiten hinter sich zu lassen: Was ihn bremst, ist die Scheu, die alte Geschichte loszulassen. Der Kreuz König als Rat ist ein großzügiger, loyaler Mann, ein guter Berater: Bevor er einen Kredit aufnimmt, sollte er jemanden mit Geschäftserfahrung fragen, dem er vertraut. Die Kreuz Sechs als Ergebnis steht für gute Geschäfte und finanzielle Unterstützung: Mit diesem Berater an seiner Seite wird der Neuanfang gelingen.' } },
];
